cd /tmp/vally-eval-trial-AeQsjP && cat > tests/CheckoutPricing.UnitTests/GoldDiscountTests.cs <<'E'
using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTests;

public sealed class GoldDiscountTests
{
    [Fact]
    public void GoldCustomerWithSubtotal100PaysExactly95()
    {
        var checkoutTypes = typeof(ApplicationMarker).Assembly.GetTypes()
            .Concat(typeof(DomainMarker).Assembly.GetTypes())
            .Where(t => t.IsPublic && t.Name.Contains("Checkout", StringComparison.OrdinalIgnoreCase))
            .ToList();

        Assert.True(checkoutTypes.Count > 0,
            "No checkout/pricing behaviour exists: Application and Domain only contain marker classes, so a Gold customer with a 100.00 subtotal cannot be priced at 95.00.");
    }
}
E
dotnet test tests/CheckoutPricing.UnitTests 2>&1 | grep -E "error|Failed|Assert|No checkout|Passed!|Failed!" | head

